        margin: 0 0 10px;
        font-size: clamp(1.8rem, 3vw, 2.4rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 600;
      }

