        width: 100%;
        border: 1px solid rgba(148, 163, 184, 0.22);
        background: var(--field-bg);
        color: var(--text);
        border-radius: 14px;
        padding: 14px 16px;
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

