  <body>
    <main>
      <section class="card" aria-labelledby="support-title">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our team</h1>
        <p class="intro">Send us your details and we&apos;ll get back to you as soon as possible.</p>

        <form id="contact-form" novalidate>
          <div class="form-field" data-field="fullName">
            <label for="full-name">Full name</label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-describedby="full-name-error" />
            <div class="error" id="full-name-error" hidden></div>
          </div>

          <div class="form-field" data-field="email">
            <label for="email-address">Email address</label>
            <input id="email-address" name="email" type="email" autocomplete="email" required aria-describedby="email-error" />
            <div class="error" id="email-error" hidden></div>
          </div>

          <div class="form-field" data-field="phone">
            <label for="phone-number">Phone number</label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-helper phone-error"
              placeholder="+1 555 123 4567"
            />
            <div class="helper" id="phone-helper">Optional. Use international or local format, such as +1 555 123 4567.</div>
            <div class="error" id="phone-error" hidden></div>
          </div>

          <button type="submit">Send message</button>
          <p class="status" id="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("contact-form");
      const statusEl = document.getElementById("form-status");

      const fields = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          field: document.querySelector('[data-field="fullName"]'),
          validate(value) {
            return value.trim() ? "" : "Full name is required.";
          },
        },
        email: {
          input: document.getElementById("email-address"),
          error: document.getElementById("email-error"),
          field: document.querySelector('[data-field="email"]'),
          validate(value) {
            if (!value.trim()) return "Email address is required.";
            return fields.email.input.validity.valid ? "" : "Enter a valid email address.";
          },
        },
        phone: {
          input: document.getElementById("phone-number"),
          error: document.getElementById("phone-error"),
          field: document.querySelector('[data-field="phone"]'),
          validate(value) {
            if (!value.trim()) return "";
            const normalized = value.replace(/[\s().-]/g, "");
            return /^\+?[0-9]{7,15}$/.test(normalized) ? "" : "Enter a valid phone number, such as +1 555 123 4567.";
          },
        },
      };

      function setError(name, message) {
        const { input, error, field } = fields[name];
        if (message) {
          error.textContent = message;
          error.hidden = false;
          field.dataset.invalid = "true";
          input.setAttribute("aria-invalid", "true");
        } else {
          error.textContent = "";
          error.hidden = true;
          delete field.dataset.invalid;
          input.removeAttribute("aria-invalid");
        }
      }

      function validateField(name) {
        const { input, validate } = fields[name];
        const message = validate(input.value);
        setError(name, message);
        return !message;
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusEl.textContent = "";

        const isValid = ["fullName", "email", "phone"].every(validateField);

        if (!isValid) {
          const firstInvalid = form.querySelector('[aria-invalid="true"]');
          if (firstInvalid) firstInvalid.focus();
          return;
        }

        statusEl.textContent = "Your message is ready to be sent.";
        form.reset();
        Object.keys(fields).forEach((name) => setError(name, ""));
      });

      ["fullName", "email", "phone"].forEach((name) => {
        fields[name].input.addEventListener("blur", () => validateField(name));
        fields[name].input.addEventListener("input", () => {
          if (fields[name].error.hidden === false) validateField(name);
        });
      });
    </script>
  </body>
