     <main>
       <section class="card" aria-labelledby="support-title">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="intro">Send us your details and we&apos;ll get back to you as soon as possible.</p>

         <form id="contact-form" novalidate>
           <div class="form-field" data-field="fullName">
